div.script:
(function () {
  const escapeHtml = value => {
    if (typeof value !== "string") {
      return "";
    }
    return value;
  };

  function enhanceEmailBody(modalEl) {
    if (!modalEl) {
      return;
    }
    const forms = modalEl.querySelectorAll('form[data-role="product-popup-form"]');
    forms.forEach(form => {
      const bodyField = form.querySelector('[name="body_html"]');
      if (!bodyField) {
        return;
      }
      const messageField = form.querySelector('textarea[name="Message"]');
      const productField = form.querySelector('input[name="Product Name"]');

      const buildBody = () => {
        const productNameRaw = (form.dataset.productName || (productField && productField.value) || '').trim();
        const messageRaw = messageField && messageField.value ? messageField.value.trim() : '';
        const bodyParts = [];
        if (productNameRaw) {
          bodyParts.push(`
Product: ${escapeHtml(productNameRaw)}`);
        }
        if (messageRaw) {
          const safeMessage = escapeHtml(messageRaw).replace(/\r?\n/g, '
');
          bodyParts.push(`
${safeMessage}`);
        }
        bodyField.value = bodyParts.join('') || '';
      };

      form.addEventListener('submit', buildBody);
      if (messageField) {
        messageField.addEventListener('input', buildBody);
        messageField.addEventListener('change', buildBody);
      }
      buildBody();
    });
  }

  function setupProductPopup(options) {
    const modalEl = document.getElementById(options.modalId);
    if (!modalEl) {
      return;
    }

    enhanceEmailBody(modalEl);

    const conditionalRequiredContainers = Array.from(modalEl.querySelectorAll('[data-required-if-visible]'));

    const isElementVisible = element => {
      if (!element) {
        return false;
      }
      if (element.closest('.d-none')) {
        return false;
      }
      let current = element;
      while (current && current !== document.body) {
        if (current.classList && current.classList.contains('d-none')) {
          return false;
        }
        const style = window.getComputedStyle(current);
        if (style.display === 'none' || style.visibility === 'hidden') {
          return false;
        }
        current = current.parentElement;
      }
      return true;
    };

    const updateConditionalRequired = () => {
      conditionalRequiredContainers.forEach(container => {
        const field = container.matches('input, select, textarea')
          ? container
          : container.querySelector('input, select, textarea');
        if (!field) {
          return;
        }
        const marker = container.querySelector('[data-role="required-marker"]');
        if (isElementVisible(container)) {
          field.setAttribute('required', 'required');
          field.setAttribute('aria-required', 'true');
          container.classList.add('s_website_form_required');
          if (marker) {
            marker.classList.remove('d-none');
          }
        } else {
          field.removeAttribute('required');
          field.removeAttribute('aria-required');
          container.classList.remove('s_website_form_required');
          if (marker) {
            marker.classList.add('d-none');
          }
        }
      });
    };

    if (conditionalRequiredContainers.length) {
      window.setTimeout(updateConditionalRequired, 0);
      const visibilityControls = modalEl.querySelectorAll('input, select');
      visibilityControls.forEach(control => {
        control.addEventListener('change', () => window.setTimeout(updateConditionalRequired, 0));
      });
      modalEl.addEventListener('o_website_form_update_visibility', () => window.setTimeout(updateConditionalRequired, 0));
      const mutationObserver = new MutationObserver(() => window.setTimeout(updateConditionalRequired, 0));
      conditionalRequiredContainers.forEach(container => {
        mutationObserver.observe(container, { attributes: true, attributeFilter: ['class', 'style'] });
      });
    }

    const form = modalEl.querySelector("form.o_mark_required");
    const successTarget = modalEl.querySelector(options.successSelector || "[data-role=\"form-result\"]");
    const thanksContainer = modalEl.querySelector("[data-role=\"thanks-container\"]");
    const thanksTemplate = modalEl.querySelector("[data-role=\"thanks-template\"]");
    const privacyNotices = Array.from(modalEl.querySelectorAll("[data-role=\"privacy-notice\"]"));
    const originalResultClass = successTarget ? successTarget.getAttribute("class") || "" : "";
    const initDelay = typeof options.initDelay === "number" ? options.initDelay : 300;
    let hasShownThanks = false;
    let successAlertObserver = null;

    const hasActiveErrors = () => {
      if (!modalEl) {
        return false;
      }
      const errorSelectors = options.errorSelectors || [
        ".o_has_error",
        ".o_invalid_field",
        ".is-invalid",
        ".invalid-feedback:not(.d-none)",
        ".alert.alert-danger:not(.d-none)",
        "[data-role=\"form-result\"].alert-danger",
        "[data-role=\"form-result\"] .alert-danger"
      ];
      const hasSelectorErrors = errorSelectors.some(selector => modalEl.querySelector(selector));
      if (hasSelectorErrors) {
        return true;
      }
      if (form && (form.classList.contains("o_has_error") || form.classList.contains("s_website_form_has_error"))) {
        return true;
      }
      return false;
    };

    const showThanks = () => {
      if (!form || !thanksContainer || !thanksTemplate || hasShownThanks) {
        return;
      }
      hasShownThanks = true;
      form.classList.add("d-none");
      thanksContainer.innerHTML = thanksTemplate.innerHTML;
      thanksContainer.classList.remove("d-none");
      if (successAlertObserver) {
        successAlertObserver.disconnect();
        successAlertObserver = null;
      }
      privacyNotices.forEach(node => node.classList.add("d-none"));
    };

    const handleSuccess = () => {
      if (hasShownThanks) {
        return;
      }
      if (successTarget) {
        successTarget.innerHTML = "";
        successTarget.setAttribute("class", originalResultClass);
      }
      modalEl.querySelectorAll(".alert.alert-success").forEach(node => node.remove());
      showThanks();
    };

    const observeSuccessAlerts = () => {
      if (successAlertObserver) {
        successAlertObserver.disconnect();
      }
      successAlertObserver = new MutationObserver(mutations => {
        if (hasShownThanks) {
          return;
        }
        const hasSuccess = mutations.some(mutation =>
          Array.from(mutation.addedNodes || []).some(node => {
            if (node.nodeType !== Node.ELEMENT_NODE) {
              return false;
            }
            if (node.classList && node.classList.contains("alert") && node.classList.contains("alert-success")) {
              return true;
            }
            return !!(node.querySelector && node.querySelector(".alert.alert-success"));
          })
        );
        if (hasSuccess) {
          handleSuccess();
        }
      });
      successAlertObserver.observe(modalEl, { childList: true, subtree: true });
    };

    const resetPopupState = () => {
      if (form) {
        form.classList.remove("d-none");
        form.reset();
      }
      hasShownThanks = false;
      if (conditionalRequiredContainers.length) {
        window.setTimeout(updateConditionalRequired, 0);
      }
      if (thanksContainer) {
        thanksContainer.innerHTML = "";
        thanksContainer.classList.add("d-none");
      }
      if (successTarget) {
        successTarget.innerHTML = "";
        successTarget.setAttribute("class", originalResultClass);
      }
      modalEl.querySelectorAll(".alert.alert-success").forEach(node => node.remove());
      privacyNotices.forEach(node => node.classList.remove("d-none"));
      observeSuccessAlerts();
    };

    if (form) {
      if (window.jQuery) {
        const $form = window.jQuery(form);
        $form.on("o_website_form_success", handleSuccess);
        $form.on("o_website_form_submit", () => {
          if (thanksContainer) {
            thanksContainer.innerHTML = "";
            thanksContainer.classList.add("d-none");
          }
          privacyNotices.forEach(node => node.classList.remove("d-none"));
          form.classList.remove("d-none");
        });
      }

      form.addEventListener("o_website_form_success", handleSuccess, true);
      form.addEventListener("o_website_form_submit", () => {
        if (thanksContainer) {
          thanksContainer.innerHTML = "";
          thanksContainer.classList.add("d-none");
        }
        privacyNotices.forEach(node => node.classList.remove("d-none"));
        form.classList.remove("d-none");
      });

      const submitButtons = modalEl.querySelectorAll(options.submitButtonSelector || ".s_website_form_send");
      const submitCheckDelay = typeof options.submitCheckDelay === "number" ? options.submitCheckDelay : 300;
      submitButtons.forEach(button => {
        button.addEventListener("click", () => {
          window.setTimeout(() => {
            if (!hasActiveErrors()) {
              handleSuccess();
            }
          }, submitCheckDelay);
        });
      });
    }

    if (successTarget) {
      const resultObserver = new MutationObserver(() => {
        if (hasShownThanks) {
          return;
        }
        const hasMessage = successTarget.textContent && successTarget.textContent.trim().length > 0;
        const hasSuccessAlert = !!(successTarget.querySelector && successTarget.querySelector(".alert.alert-success"));
        if (hasMessage || hasSuccessAlert) {
          handleSuccess();
        }
      });
      resultObserver.observe(successTarget, { childList: true, subtree: true });
    }

    modalEl.addEventListener("show.bs.modal", () => {
      resetPopupState();
    });

    modalEl.addEventListener("shown.bs.modal", () => {
      window.setTimeout(() => {
        try {
          if (window.odoo?.website?.website_form?.init) {
            window.odoo.website.website_form.init();
          }
        } catch (err) {
          console.error("Error initializing website_form in modal:", err);
        }
      }, initDelay);
      if (conditionalRequiredContainers.length) {
        window.setTimeout(updateConditionalRequired, initDelay);
      }
    });

    modalEl.addEventListener("hidden.bs.modal", () => {
      resetPopupState();
    });

    if (options.openButtonSelector) {
      const showModal = () => {
        if (typeof bootstrap !== "undefined" && bootstrap.Modal) {
          const modalInstance = bootstrap.Modal.getOrCreateInstance(modalEl);
          modalInstance.show();
          return true;
        }
        if (window.jQuery && typeof window.jQuery(modalEl).modal === "function") {
          window.jQuery(modalEl).modal("show");
          return true;
        }
        return false;
      };

      document.querySelectorAll(options.openButtonSelector).forEach(trigger => {
        trigger.addEventListener("click", event => {
          event.preventDefault();
          if (!showModal()) {
            console.warn("Modal dependencies missing for", options.modalId);
          }
        });
      });
    }

    observeSuccessAlerts();
  }

  document.addEventListener("DOMContentLoaded", function () {
    const popups = [
      { modalId: "infoRequestModal", openButtonSelector: "#openFormBtn", initDelay: 300 },
      { modalId: "requestCustomizationModal", initDelay: 300 },
      { modalId: "modal3DForm", initDelay: 600 }
    ];
    popups.forEach(setupProductPopup);
  });
})();

document.addEventListener("DOMContentLoaded", function() {
  const popup = document.getElementById("popupCatalogo");
  if (!popup) {
    return;
  }

  const close = popup.querySelector(".close-popup");
  const catalogField = document.getElementById("catalogName");
  const subjectField = document.getElementById("oogxyy4kqwu");
  const form = popup.querySelector("form.o_mark_required");
  const submitButton = form ? form.querySelector(".s_website_form_send") : null;
  const successTarget = popup.querySelector("#s_website_form_result");
  const thanksContainer = popup.querySelector("#popupThanksContainer");
  const thanksTemplate = popup.querySelector("#popupThanksTemplate");
  const privacyNotice = document.getElementById("privacyPolicyNotice");
  const defaultSubjectValue = subjectField ? subjectField.value : "";
  const defaultCatalogValue = catalogField ? catalogField.value : "";
  const originalResultClass = successTarget ? successTarget.getAttribute("class") || "" : "";
  let hasShownThanks = false;
  let successAlertObserver = null;

  const toggleProfessionalRequirements = () => {
    if (!form) {
      return;
    }
    const isProfessional = !!form.querySelector('input[name="Custom Text"][value="Professional"]:checked');
    form.querySelectorAll('[data-professional-required="true"]').forEach(field => {
      const fieldContainer = field.closest('.s_website_form_field');
      const mark = fieldContainer ? fieldContainer.querySelector('.s_website_form_mark[data-professional-mark="true"]') : null;
      if (isProfessional) {
        field.setAttribute('required', 'required');
        field.setAttribute('aria-required', 'true');
        if (fieldContainer) {
          fieldContainer.classList.add('s_website_form_required');
        }
        if (mark) {
          mark.classList.remove('d-none');
        }
      } else {
        field.removeAttribute('required');
        field.removeAttribute('aria-required');
        if (fieldContainer) {
          fieldContainer.classList.remove('s_website_form_required');
        }
        if (mark) {
          mark.classList.add('d-none');
        }
      }
    });
  };

  if (form) {
    toggleProfessionalRequirements();
    form.querySelectorAll('input[name="Custom Text"]').forEach(radio => {
      radio.addEventListener('change', toggleProfessionalRequirements);
    });
  }

  const hasActiveErrors = () => {
    if (!popup) {
      return false;
    }
    const errorSelectors = [
      ".o_has_error",
      ".o_invalid_field",
      ".is-invalid",
      ".invalid-feedback:not(.d-none)",
      ".alert.alert-danger:not(.d-none)",
      "#s_website_form_result.alert-danger",
      "#s_website_form_result .alert-danger"
    ];
    return errorSelectors.some(selector => popup.querySelector(selector));
  };

  const showThanks = () => {
    if (!form || !thanksContainer || !thanksTemplate || hasShownThanks) {
      return;
    }
    hasShownThanks = true;
    form.classList.add("d-none");
    thanksContainer.innerHTML = thanksTemplate.innerHTML;
    thanksContainer.classList.remove("d-none");
    if (successAlertObserver) {
      successAlertObserver.disconnect();
      successAlertObserver = null;
    }
    if (privacyNotice) {
      privacyNotice.classList.add("d-none");
    }
  };

  const handleSuccess = () => {
    if (successTarget) {
      successTarget.innerHTML = "";
      successTarget.setAttribute("class", originalResultClass);
    }
    popup.querySelectorAll('.alert.alert-success').forEach(node => node.remove());
    showThanks();
  };

  const observeSuccessAlerts = () => {
    if (!popup) {
      return;
    }
    if (successAlertObserver) {
      successAlertObserver.disconnect();
    }
    successAlertObserver = new MutationObserver(mutations => {
      if (hasShownThanks) {
        return;
      }
      const hasSuccessAlert = mutations.some(mutation => {
        return Array.from(mutation.addedNodes || []).some(node => {
          if (node.nodeType !== Node.ELEMENT_NODE) {
            return false;
          }
          const element = node;
          if (element.classList && element.classList.contains('alert') && element.classList.contains('alert-success')) {
            return true;
          }
          return !!(element.querySelector && element.querySelector('.alert.alert-success'));
        });
      });
      if (hasSuccessAlert) {
        handleSuccess();
      }
    });
    successAlertObserver.observe(popup, { childList: true, subtree: true });
  };

  const resetPopupState = () => {
    if (form) {
      form.classList.remove("d-none");
      form.reset();
      toggleProfessionalRequirements();
    }
    hasShownThanks = false;
    if (catalogField) {
      catalogField.value = defaultCatalogValue;
    }
    if (subjectField) {
      subjectField.value = defaultSubjectValue;
    }
    if (thanksContainer) {
      thanksContainer.innerHTML = "";
      thanksContainer.classList.add("d-none");
    }
    if (successTarget) {
      successTarget.innerHTML = "";
      successTarget.setAttribute("class", originalResultClass);
    }
    popup.querySelectorAll('.alert.alert-success').forEach(node => node.remove());
    if (privacyNotice) {
      privacyNotice.classList.remove("d-none");
    }
    observeSuccessAlerts();
  };

  if (form) {
    if (window.jQuery) {
      const $form = window.jQuery(form);
      $form.on("o_website_form_success", handleSuccess);
      $form.on("o_website_form_submit", () => {
        if (privacyNotice) {
          privacyNotice.classList.remove("d-none");
        }
        if (thanksContainer) {
          thanksContainer.innerHTML = "";
          thanksContainer.classList.add("d-none");
        }
        form.classList.remove("d-none");
      });
    }

    form.addEventListener("o_website_form_success", handleSuccess, true);

    if (successTarget) {
      const observer = new MutationObserver(() => {
        const hasMessage = successTarget.textContent && successTarget.textContent.trim().length > 0;
        if (hasMessage) {
          handleSuccess();
        }
      });
      observer.observe(successTarget, { childList: true, subtree: true });
    }
  }

  if (submitButton) {
    submitButton.addEventListener("click", () => {
      window.setTimeout(() => {
        if (!hasActiveErrors()) {
          handleSuccess();
        }
      }, 300);
    });
  }

  observeSuccessAlerts();

  document.querySelectorAll(".download-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      resetPopupState();
      const nome = btn.dataset.catalogo;
      if (catalogField && nome) {
        catalogField.value = nome;
      }
      if (subjectField && nome) {
        subjectField.value = `${nome} Request`;
      }
      popup.style.display = "flex";
    });
  });

  if (close) {
    close.addEventListener("click", () => {
      popup.style.display = "none";
    });
  }

  popup.addEventListener("click", event => {
    if (event.target === popup) {
      popup.style.display = "none";
    }
  });
});
